create table if not exists attendance(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),sales_executive_id uuid not null references sales_executives(id),work_date date not null,check_in timestamptz,check_out timestamptz,latitude numeric(10,7),longitude numeric(10,7),accuracy_m numeric(10,2),photo_object text,created_at timestamptz default now(),unique(tenant_id,sales_executive_id,work_date));
create table if not exists dsr(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),sales_executive_id uuid not null references sales_executives(id),customer_id uuid references customers(id),visit_at timestamptz default now(),latitude numeric(10,7),longitude numeric(10,7),photo_object text,notes text,order_id uuid references orders(id),idempotency_key text,created_at timestamptz default now(),unique(tenant_id,idempotency_key));
